-- Restore the checked-in product catalog for clean local databases. The UI only falls back to demo products when this table is empty, and those demo IDs do not exist in the database, so favorite/order foreign keys reject them.
ON CONFLICT (id) DO NOTHING;

SELECT setval(pg_get_serial_sequence('public.products', 'id'), COALESCE(MAX(id), 1), MAX(id) IS NOT NULL)
FROM public.products;
