INSERT INTO public.products (id, name, badge, image, specs, active, gallery, category, created_at, description, member_price, original_price, live_recommended)
VALUES
  (13, 'Soothing Aromatic Serum No.1', NULL, 'https://yiiptvateqtjcoqtsmot.supabase.co/storage/v1/object/public/product-images/3c830d57-cc84-4661-b715-204989ae63aa.jpeg', '[]'::jsonb, true, '[]'::jsonb, 'Beauty', '2026-09-02T07:49:26.060476+00:00'::timestamptz, '<p><strong>An aromatic treatment serum to cool and soothe redness in the skin. Our best seller has a blend of potent natural essential oils and nourishing botanicals making this formula ideal for encouraging skin soothing,&nbsp;</strong><strong>and calming of the senses.</strong></p>&nbsp;<p><strong>Skin type/condition:&nbsp;</strong>For all skin types especially with the condition of sensitive skin related to environmental irritants.</p>&nbsp;<p><strong>Benefits:</strong>&nbsp;This unique blend of essential oils soothe and help reduce redness in the skin. Skin softening and nourishing Avocado and Hazelnut oils improve and condition skin texture.</p>&nbsp;<p><strong>Key ingredients:&nbsp;</strong>Hazelnut oil nourishes with Vitamins A B and E, Soya oil replenishes with vitamins A D and E. Expertly hand blended essential oils of Lavender Geranium Cypress Eucalyptus and Sandalwood to balance, soothe and condition skin tissues.</p>&nbsp;<p><strong>How to use</strong>: After cleansing, gently smooth 3-4 drops over face and neck. Continue with suitable toner and moisturiser.</p>&nbsp;<p><strong>Ingredients:</strong>&nbsp;Glycine Soja oil, Corylus Avellana seed oil, Persea Gratissima oil, Triticum Vulgare germ oil, Pelargonium Graveolens flower oil, Lavandula Angustifolia oil, Eucalyptus Globulus leaf oil, Cupressus Sempervirens leaf oil, Santalum Album wood oil, Linalool*, Geraniol*, Limonene*.Citronellol* Farnesol*, Coumarin*.<br><br>*Naturally occuring component within essential oils.<br><br>We make every attempt to ensure all ingredients listed on this website are accurate; however, formulations are subject to change from time to time.<br>Please refer to the ingredients list on your product packaging for the most accurate ingredients listing.</p>', 18000, 18400, true),
  (15, 'SOOTHING SKINCARE COLLECTION KIT', 'Popular', 'https://yiiptvateqtjcoqtsmot.supabase.co/storage/v1/object/public/product-images/8f8474e0-1660-44d9-9c36-e7d230dd4476.jpg', '[{"label": "Soothing Cleanser", "value": "50ml"}, {"label": "Soothing Toner", "value": "50ml"}, {"label": "Refining Eye Gel", "value": "15ml"}, {"label": "Soothing Moisture Lotion", "value": "50ml"}]'::jsonb, true, '["https://yiiptvateqtjcoqtsmot.supabase.co/storage/v1/object/public/product-images/788c2f32-9590-4852-916f-afaee6670d2b.jpg", "https://yiiptvateqtjcoqtsmot.supabase.co/storage/v1/object/public/product-images/b4903436-22b2-4cbe-8004-6c106624dded.jpg"]'::jsonb, 'Beauty', '2026-09-04T08:28:36.728682+00:00'::timestamptz, '<p><strong>The Soothing Skincare Collection Kit is ideal for dry, ageing, mature or sensitive skin.</strong></p><p>The products within this kit contain essential oils of Cypress, Eucalyptus, Geranium, Lavender and Sandalwood which gently hydrate and nourish the skin.</p><p><br></p><p><strong>The kit contains:<br></strong>Soothing Cleanser 50ml<br>Soothing Toner 50ml<br>Refining Eye Gel 15ml<br>Soothing Moisture Lotion 50ml</p><p>Skincare Kits are the perfect way to trial our collections and discover the perfect products for your skin. This kit gives approximately 2-3 weeks use.</p><p><strong>More Information</strong></p><ul><li>Vegan friendly Yes</li><li>Pregnancy safe Yes</li><li>Ageing Yes</li><li>Dry and Dehydrated Yes</li><li>Sensitivity and redness Yes</li></ul>', 44000, 44300, true),
  (16, 'Clear Cleanse', 'New', 'https://yiiptvateqtjcoqtsmot.supabase.co/storage/v1/object/public/product-images/af903b48-cea9-4ee7-af93-b3eb381670da.jpeg', '[]'::jsonb, true, '["https://yiiptvateqtjcoqtsmot.supabase.co/storage/v1/object/public/product-images/3d7b7a9d-e75b-443c-b749-4902fd93829a.jpeg", "https://yiiptvateqtjcoqtsmot.supabase.co/storage/v1/object/public/product-images/49b0af53-527b-4748-ac1c-2b6da209bdbf.jpg"]'::jsonb, 'Beauty', '2026-09-04T08:56:30.814133+00:00'::timestamptz, '<p><strong>A finely textured oil formulated to gently yet effectively pre-cleanse all skin types. Nourishing, lightweight oils effortlessly dissolve makeup and sebum whilst citrus essential oils provide a zesty, uplifting aroma. Leaves skin thoroughly clean of debris ready for the second cleanse.</strong></p><p><strong>Skin type/condition:</strong>&nbsp;All skin types and conditions except hypersensitive.</p><p><strong>Benefits:</strong>&nbsp;Highly effective for removing all traces of makeup sebum and skin debris. Softens and nourishes the skin as it cleans deep down.&nbsp;Quickly removes waterproof mascara.</p><p><strong>Key ingredients:</strong>&nbsp;Peach kernel oil gently dissolves sebum and makeup. Argan oil rich in nutrients ensures the skin remains supple. Calendula and Green Tea extracts soothe and condition the skin.</p><p><strong>How to use:</strong>&nbsp;Dispense into dry hands and massage over dry face. If hypersensitive around the eye area apply with dampened cotton pad. Wet hands and continue massaging to emulsify. Rinse with tepid water. Continue with cleanser according to skin type.</p><p><strong>More Information</strong></p><ul><li>Vegan friendly Yes</li><li>Pregnancy safe Yes</li><li>Ageing Yes</li><li>Breakouts and acne Yes</li><li>Combination Yes</li><li>Dry and Dehydrated Yes</li><li>Normal and Balanced Yes</li><li>Uneven skin tone Yes</li><li>Oily Yes</li></ul>', 27500, 27900, false),
  (17, 'SOOTHING TONER', 'Best Seller', 'https://yiiptvateqtjcoqtsmot.supabase.co/storage/v1/object/public/product-images/09787da0-151e-4275-9d74-0a93e071262f.jpg', '[]'::jsonb, true, '["https://yiiptvateqtjcoqtsmot.supabase.co/storage/v1/object/public/product-images/fd2c61be-9a45-4292-9b08-808431817a6b.jpg", "https://yiiptvateqtjcoqtsmot.supabase.co/storage/v1/object/public/product-images/dda43ee4-b1b0-4b3d-90e7-bf2ec289fd4c.jpg"]'::jsonb, 'Beauty', '2026-09-04T09:01:42.546709+00:00'::timestamptz, '<p><strong>A soothing spritz formulated with lavender and chamomile waters to soothe and calm the skin while hydrating aloe vera refreshes and cools.</strong></p>&nbsp;<p><strong>Skin type/condition:&nbsp;</strong>Dry, mature or sensitive.</p>&nbsp;<p><strong>Benefits:</strong>&nbsp;Fine mist of water based essential oils freshen and soothe the skin. Hydrating and soothing formula prepares the skin for moisturising. May be used to refresh the skin throughout the day even over make-up</p>&nbsp;<p><strong>Key ingredients:&nbsp;</strong>Aloe vera juice intensively hydrates the skin with moisture, softens and soothes sensitivity. Chamomile offers calming benefits to reddened skin whilst soothing and calming the mindset. Lavender reduces redness whilst conditioning. Witch hazel imparts a refreshing, mildly astringent quality.</p>&nbsp;<p><strong>How to use:&nbsp;</strong>With closed eyes spray a fine mist to face and neck, continue with suitable Eve Taylor moisturiser. May be spritzed onto the skin throughout the day to refresh and soothe times of irritation.<br><br><strong>Ingredients:</strong>&nbsp;Aqua, Aloe Barbadensis Leaf Juice, Hamamelis Virginiana Water, Lavandula Angustifolia Oil, Anthemis Noblilis Flower Oil, Lonicera Caprifolium Extract, Lonicera Japponica Extract, Deceth-7, PEG-40, Hydrogenated Caster Oil, PEG-26- Buteth-26, Citric Acid, Potassium Sorbate, Sodium Benzoate, Phenoxyethanol, Linalool*, Limonene*.<br><br>*Naturally occuring component within essential oils.<br><br>We make every attempt to ensure all ingredients listed on this website are accurate; however, formulations are subject to change from time to time.<br>Please refer to the ingredients list on your product packaging for the most accurate ingredients listing.</p>', 17900, 18000, true),
  (14, 'Ultra Soothing Moisture Cream', 'Popular', 'https://yiiptvateqtjcoqtsmot.supabase.co/storage/v1/object/public/product-images/42630fdb-3419-45f4-b7bb-6715c6f4d053.jpg', '[]'::jsonb, true, '["https://yiiptvateqtjcoqtsmot.supabase.co/storage/v1/object/public/product-images/372885f6-c26b-4e1d-aaa4-200b39786963.jpg", "https://yiiptvateqtjcoqtsmot.supabase.co/storage/v1/object/public/product-images/b2db684c-7dfc-49c4-95e5-d27f7456dad5.jpg"]'::jsonb, 'Beauty', '2026-09-04T07:45:10.165741+00:00'::timestamptz, '<p><strong>Plant extracts of borage seed and comfrey soothe while sunflower oil improves skin nourishment, collectively providing protection to help replenish the skin and defend against environmental aggressors.&nbsp;<br></strong><br></p><p><strong>Skin type/condition:&nbsp;</strong>Ultra dry, sensitive, dehydrated skin.<br><br><strong>Benefits:</strong>&nbsp;Essential Oil free formulation creates the perfect moisturiser for even the most sensitive skins. Botanical extracts sooth and defend against environmental aggressors.&nbsp;</p>&nbsp;<p><strong>Key ingredients:&nbsp;</strong>Borage seed oil helps sooth the skin. Comfrey imparts powerful benefits to help replenish. A complex of botanical extracts defend against environmental assault.&nbsp;</p>&nbsp;<p><strong>How to use:</strong>&nbsp;After toning, apply to the skin using light fingertip pressure in upward strokes to face, neck and décolleté. For maximum skin protection continue with suitable solar protection.</p>&nbsp;<p><strong>Ingredients:</strong>&nbsp;Aqua, Helianthus annuus Seed Oil, Glycerin, Borago officinalis Seed Oil, Glyceryl Stearate, Cetearyl Alcohol, Chamomilla recutita Flower Extract, Panax ginseng Root Extract, Symphytum officinale Leaf Extract, Lavandula angustifolia Flower Extract, Glycyrrhiza glabra Root Extract, Sodium Benzoate, Potassium Sorbate, Dimethicone, Stearic Acid, Magnesium Aluminum Silicate, Prunus amygdalus dulcis Oil, Phenoxyethanol, Caprylyl Glycol, Decylene Glycol, Tocopheryl Acetate, Sodium PCA, Triethanolamine, Aloe barbadensis Leaf Juice Powder, Maltodextrin, Potassium Sorbate, Ascorbic Acid, Disodium EDTA, Citric Acid, Anthemis nobilis Flower Oil.<br><br>We make every attempt to ensure all ingredients listed on this website are accurate; however, formulations are subject to change from time to time.<br>Please refer to the ingredients list on your product packaging for the most accurate ingredients listing.<br><br>The borage seed oil within this moisturiser imparts a unique characteristic aroma. This scent is natural and is not an sign of rancidity.</p><br>', 17500, 17800, true),
  (18, 'DAILY SKIN DEFENCE MOISTURISER SPF50', NULL, 'https://yiiptvateqtjcoqtsmot.supabase.co/storage/v1/object/public/product-images/bdc98632-7b82-443e-bc43-73de11c53a9d.webp', '[]'::jsonb, true, '[]'::jsonb, 'Beauty', '2026-09-04T09:13:52.516803+00:00'::timestamptz, '<p><strong>An easily absorbed daily defence moisturiser with Shea Butter and Xylitol. A high protection moisturiser guarding against sun damage and premature skin ageing.</strong><br><br><strong>Skin type/condition:</strong>&nbsp;All skin types and conditions.<br><br><strong>Benefits:</strong>&nbsp;High protection formulation is ideal for when exposed to direct sunlight for extended periods. May be used following advanced treatments such as microdermabrasion, chemical peels, or dermaplaning. Defends against UV induced sun damage. Nourishing yet easily absorbed ingredients offer skin moisturising and hydrating benefits.<br><br><strong>Key ingredients:</strong>&nbsp;Octinoxate Octocrylene and Octyl Triazone sunscreens provide high protection against UVA and UVB rays the main cause of premature skin ageing. Shea Butter impart nourishing benefits. Sugar based Xylitol intensively hydrates moisture depleted skin. This blend of organic/chemical-based sunscreens works by absorbing Ultra Violet light, converting it to heat and dissipating it from the body.&nbsp;<br><br><strong>How to use:</strong>&nbsp;Apply using light fingertip pressure in upward strokes to face and neck. Use caution when applying sunscreen near the eye area. May be worn alone as a moisturiser, layered over moisture lotions or creams or mixed with moisture lotions, creams or liquid foundation*.&nbsp;<br><br>*When mixing with moisture lotions or creams the level of SPF will be reduced.<br><br><strong>More Information</strong></p><ul><li>Essential oil free Yes</li><li>Pregnancy safe Yes</li><li>Ageing Yes</li><li>Breakouts and acne Yes</li><li>Combination Yes</li><li>Dry and Dehydrated Yes</li><li>Normal and Balanced Yes</li><li>Uneven skin tone Yes</li><li>Sensitivity and redness Yes</li><li>Oily Yes</li></ul>', 22900, 23400, false)
